// Normalize Shopify product data
const items = $input.all();
const normalized = [];

items.forEach(item => {
  const product = item.json;

  if (product.variants && Array.isArray(product.variants)) {
    product.variants.forEach(variant => {
      normalized.push({
        platform: 'shopify',
        product_id: product.id.toString(),
        variant_id: variant.id.toString(),
        sku: variant.sku || `SHOPIFY-${product.id}-${variant.id}`,
        title: `${product.title} - ${variant.title}`,
        stock_quantity: variant.inventory_quantity || 0,
        price: parseFloat(variant.price || 0),
        synced_at: new Date().toISOString()
      });
    });
  }
});

return normalized.map(item => ({ json: item }));

// Normalize WooCommerce product data
const items = $input.all();
const normalized = [];

items.forEach(item => {
  const product = item.json;

  normalized.push({
    platform: 'woocommerce',
    product_id: product.id.toString(),
    variant_id: product.id.toString(),
    sku: product.sku || `WOO-${product.id}`,
    title: product.name,
    stock_quantity: product.stock_quantity || 0,
    price: parseFloat(product.price || 0),
    synced_at: new Date().toISOString()
  });

  // Handle variations
  if (product.variations && Array.isArray(product.variations)) {
    product.variations.forEach(varId => {
      normalized.push({
        platform: 'woocommerce',
        product_id: product.id.toString(),
        variant_id: varId.toString(),
        sku: `WOO-${product.id}-${varId}`,
        title: `${product.name} - Variation ${varId}`,
        stock_quantity: 0,
        price: parseFloat(product.price || 0),
        synced_at: new Date().toISOString()
      });
    });
  }
});

return normalized.map(item => ({ json: item }));

// Consolidate inventory across platforms by SKU
const allItems = $input.all();
const inventoryMap = new Map();
const databaseInventory = new Map();

// Separate database records
allItems.forEach(item => {
  const data = item.json;

  if (data.warehouse_location) {
    // This is from database
    databaseInventory.set(data.sku, data);
  } else {
    // This is from e-commerce platforms
    const sku = data.sku;

    if (!inventoryMap.has(sku)) {
      inventoryMap.set(sku, {
        sku: sku,
        title: data.title,
        platforms: {},
        total_stock: 0,
        price: data.price,
        last_synced: data.synced_at
      });
    }

    const inventory = inventoryMap.get(sku);
    inventory.platforms[data.platform] = {
      product_id: data.product_id,
      variant_id: data.variant_id,
      stock: data.stock_quantity
    };
    inventory.total_stock += data.stock_quantity;
  }
});

// Create consolidated records with sync recommendations
const consolidated = [];
const lowStockAlerts = [];
const syncActions = [];

inventoryMap.forEach((inventory, sku) => {
  const dbRecord = databaseInventory.get(sku);
  const masterStock = dbRecord ? dbRecord.stock_quantity : inventory.total_stock;

  // Check if sync needed
  Object.entries(inventory.platforms).forEach(([platform, data]) => {
    if (data.stock !== masterStock) {
      syncActions.push({
        sku: sku,
        platform: platform,
        product_id: data.product_id,
        variant_id: data.variant_id,
        current_stock: data.stock,
        target_stock: masterStock,
        action: 'update'
      });
    }
  });

  // Low stock alert (threshold: 10)
  if (masterStock < 10) {
    lowStockAlerts.push({
      sku: sku,
      title: inventory.title,
      current_stock: masterStock,
      platforms: Object.keys(inventory.platforms),
      alert_level: masterStock === 0 ? 'CRITICAL' : 'WARNING'
    });
  }

  consolidated.push({
    sku: sku,
    title: inventory.title,
    master_stock: masterStock,
    platforms: inventory.platforms,
    price: inventory.price,
    needs_sync: syncActions.filter(a => a.sku === sku).length > 0,
    low_stock: masterStock < 10,
    synced_at: new Date().toISOString()
  });
});

return [{
  json: {
    consolidated: consolidated,
    syncActions: syncActions,
    lowStockAlerts: lowStockAlerts,
    summary: {
      total_products: consolidated.length,
      products_needing_sync: syncActions.length,
      low_stock_items: lowStockAlerts.length,
      critical_items: lowStockAlerts.filter(a => a.alert_level === 'CRITICAL').length
    }
  }
}];

// Format low stock alerts for Slack
const data = $input.first().json;
const alerts = data.lowStockAlerts;

let message = `🚨 *Inventory Low Stock Alert*\n\n`;
message += `Total items requiring attention: ${alerts.length}\n`;
message += `Critical (Out of Stock): ${alerts.filter(a => a.alert_level === 'CRITICAL').length}\n\n`;

// Group by alert level
const critical = alerts.filter(a => a.alert_level === 'CRITICAL');
const warnings = alerts.filter(a => a.alert_level === 'WARNING');

if (critical.length > 0) {
  message += `*🔴 CRITICAL - Out of Stock:*\n`;
  critical.forEach(alert => {
    message += `• ${alert.title} (SKU: ${alert.sku})\n`;
    message += `  Platforms: ${alert.platforms.join(', ')}\n`;
  });
  message += `\n`;
}

if (warnings.length > 0) {
  message += `*🟡 WARNING - Low Stock (< 10 units):*\n`;
  warnings.slice(0, 10).forEach(alert => {
    message += `• ${alert.title} (SKU: ${alert.sku})\n`;
    message += `  Stock: ${alert.current_stock} | Platforms: ${alert.platforms.join(', ')}\n`;
  });

  if (warnings.length > 10) {
    message += `\n... and ${warnings.length - 10} more items\n`;
  }
}

message += `\n_Generated at ${new Date().toLocaleString()}_`;

return {
  json: {
    message: message,
    alertCount: alerts.length,
    criticalCount: critical.length
  }
};
